INSERT INTO `item_translations` (`id`, `item_id`, `language_id`, `name`, `description`, `address`, `rejected_reason`, `admin_edit_reason`, `created_at`, `updated_at`) VALUES
(1, 13, 1, 'Samsung 28L Convection Microwave Oven', 'Premium microwave oven with Slim Fry technology, 28L capacity, and elegant black finish. Perfect for grilling, baking, and healthy frying.', 'Tirunelveli, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:29', '2026-04-28 00:26:13'),
(2, 12, 1, 'Nutribullet Pro 900 High-Speed Blender', 'Transform ordinary food into superfood. Powerful 900-watt motor and unique extraction blades blend toughest ingredients into silky smoothies.', 'Ramanathapuram, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:13'),
(3, 11, 1, 'Prestige Iris Plus 750W Mixer Grinder', 'Comes with 3 stainless steel jars and 1 juicer jar. Ergonomic handle design and superior 750W motor for all your grinding and mixing needs.', 'Usilampatti, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:13'),
(4, 10, 1, 'Samsung Galaxy S24 Ultra - 512GB', 'Experience the future of AI with the Galaxy S24 Ultra. Titanium frame, 200MP camera, and the fastest Snapdragon processor yet.', 'Melur, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:13'),
(5, 9, 1, 'Diamond Halo 14K Gold Engagement Ring', 'A stunning 1-carat round brilliant diamond surrounded by a halo of micro-pave diamonds. 14K white gold band. Certificate included.', 'Karaikudi, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:12'),
(6, 8, 1, 'Sony PlayStation 5 Console (Digital Edition)', 'The PS5 Digital Edition unleashes new gaming possibilities. Experience lightning fast loading and an all-new generation of incredible PlayStation games.', 'Rajapalayam, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:12'),
(7, 7, 1, '2024 BMW M4 Competition Coupe', 'Finished in Isle of Man Green metallic. 503 hp, 0-60 in 3.4s. All-wheel drive, carbon fiber trim, and premium Merino leather interior.', 'Virudhunagar, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:12'),
(8, 6, 1, 'Men\'s Handcrafted Italian Leather Jacket', 'Made from 100% genuine Italian calfskin leather. Slim fit design with premium hardware and silk lining. A timeless classic for any wardrobe.', 'Sivakasi, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:12'),
(9, 5, 1, 'Dyson V15 Detect Absolute Cordless Vacuum', 'The most powerful, intelligent cordless vacuum. Lasers reveal microscopic dust, and acoustic piezo sensor counts and measures dust particles.', 'Theni, Tamil Nadu, India', NULL, NULL, '2026-04-27 23:50:30', '2026-04-28 00:26:12'),
(10, 17, 1, 'Designer Silk Salwar Kameez - Embroidered Festive Wear', 'Elegant designer salwar kameez made from premium silk. Features intricate embroidery work on the neck and dupatta. Perfect for weddings and festive occasions.', 'Virudhunagar, Tamil Nadu, India', NULL, NULL, '2026-04-28 00:10:07', '2026-04-28 00:26:13'),
(11, 16, 1, 'Banarasi Silk Saree - Handwoven with Zari Border', 'Authentic handwoven Banarasi silk saree with traditional zari border and pallu. Includes matching blouse piece. Luxurious feel and timeless design.', 'Sivakasi, Tamil Nadu, India', NULL, NULL, '2026-04-28 00:10:07', '2026-04-28 00:26:13'),
(12, 15, 1, 'Floral Summer Maxi Dress - Lightweight Breathable Cotton', 'Beautiful floral print maxi dress perfect for summer outings. Made from high-quality breathable cotton to keep you cool and stylish.', 'Theni, Tamil Nadu, India', NULL, NULL, '2026-04-28 00:10:07', '2026-04-28 00:26:13'),
(13, 14, 1, 'Premium Supima Cotton T-Shirt - Slim Fit, Navy Blue', 'Crafted from 100% premium Supima cotton for exceptional softness and durability. Features a classic crew neck and tailored slim fit.', 'Dindigul, Tamil Nadu, India', NULL, NULL, '2026-04-28 00:10:08', '2026-04-28 00:26:13');
